CREATE TABLE ai_reviews(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,incident_id uuid NOT NULL REFERENCES incidents(id),model text NOT NULL,rubric_version text NOT NULL,decision text NOT NULL CHECK(decision IN ('publish','merge','reject','hold')),confidence int,reason text NOT NULL,judgement jsonb,unavailable text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(incident_id,rubric_version));
